Definition stats_ok (h : hstats) : Prop :=
  1 <= hs_tableLog h <= HUF_TABLELOG_MAX /\
  Zlength (hs_weights h) = hs_nbSymbols h /\ 2 <= hs_nbSymbols h <= HUF_SYMBOLVALUE_MAX + 1 /\
  Forall (fun w => 0 <= w <= hs_tableLog h) (hs_weights h) /\
  Zlength (hs_rank h) = HUF_TABLELOG_MAX + 1 /\
  (forall w, 0 <= w <= HUF_TABLELOG_MAX -> Znth w (hs_rank h) = Z.of_nat (count_occ Z.eq_dec (hs_weights h) w)) /\
  ksum (hs_weights h) = 2^(hs_tableLog h).

Section StatsOK.
  Variable src : list Z.
  Hypothesis RS : read_ncount_safe_stmt.
  Hypothesis HB : all_bytes src.
  Let len : Z := Zlength src.

  Lemma direct_loop_ok oSize : 0 <= oSize < 256 -> (oSize + 1) / 2 + 1 <= len ->
    forall fuel n acc, 0 <= n -> n mod 2 = 0 -> Z.max 0 (oSize - n) <= 2 * (Z.of_nat fuel - 1) ->
      Forall (fun w => 0 <= w <= 15) acc ->
      exists cells, direct_loop src fuel n oSize acc = Ok cells /\ Forall (fun w => 0 <= w <= 15) cells /\
        Zlength cells >= Zlength acc + (oSize - n).
Proof.
