  Lemma collect_loop_ok : forall ws rank wt,
    Forall (fun w => 0 <= w) ws -> Zlength rank = 13 ->
    (forall v, 0 <= v <= 12 -> 0 <= Znth v rank /\ Znth v rank + Zlength ws < 2^32) ->
    0 <= wt -> wt + Zlength ws * 2^11 < 2^32 ->
    (exists rank' T, collect_loop ws rank wt = Ok (rank', T) /\ Forall (fun w => 0 <= w <= 12) ws /\ Zlength rank' = 13 /\
       (forall v, 0 <= v <= 12 -> Znth v rank' = Znth v rank + Z.of_nat (count_occ Z.eq_dec ws v)) /\ T = wt + ksum ws)
    \/ collect_loop ws rank wt = Err ZSTD_error_corruption_detected.
Proof.
